import { queryExecutionClient } from '@dynatrace-sdk/client-query';
import { httpClient } from '@dynatrace-sdk/http-client';

// All-in-one FortiGate -> cno.* bridge. Does DQL + transform + ingest in a single JS task
// because: (1) the execute-dql-query workflow task caps at 1000 records, which clips the
// interface fleet (~1069 series); the SDK call accepts maxResultRecords. (2) the external
// live.dynatrace.com host is unreachable from the workflow httpClient, so ingest uses the
// apps-domain relative path with a classic Api-Token header.
//
// AUTH:
//   * DQL reads use the workflow identity bearer (needs storage:metrics:read + storage:buckets:read
//     granted in Workflow Authorization).
//   * /api/v2/metrics/ingest is a classic endpoint; the platform bearer returns 'Invalid app context'.
//     The classic Api-Token below is embedded inline (rotate here when you rotate it in the tenant).

// REPLACE_ME_INGEST_TOKEN — a Dynatrace Api-Token (dt0c01.*) with the metrics.ingest scope.
// Classic token because /api/v2/metrics/ingest rejects platform OAuth bearers from workflows
// ('Invalid app context'). The Credential Vault cannot be used here: a plain GET on a vault
// TOKEN credential does not return the plaintext for security, and no other SDK path exposes
// it. Inline is the pragmatic choice; see the project's CLAUDE.md hard-rule #6 if you need a
// different pattern for your fork.
const INGEST_TOKEN = 'REPLACE_ME_INGEST_TOKEN';
const INGEST_HOST  = 'REPLACE_ME_TENANT.live.dynatrace.com';   // e.g. abc12345.live.dynatrace.com

// Fetched once per run from the FortiGate monitoring configs — maps management IP to the
// human-readable description (e.g. '192.0.2.10' -> 'SITE-A-FGT'). The description
// drives both the Topology label AND the role inference (inferRole looks for 'sdwan'/'core'
// substrings), which is why we suffix branches with ' (sdwan)' below so they land on the
// wan-edge tier instead of defaulting to 'other' and piling onto a single Y row.
let NAME_OF = {};
async function loadDeviceNames() {
  // Platform API — the workflow identity's bearer has extensions:configurations:read via the
  // auth settings, so httpClient works. The classic Api-Token used for ingest does NOT.
  try {
    const res = await httpClient.send({
      url: `/platform/extensions/v2/extensions/com.dynatrace.extension.fortigate/monitoring-configurations?page-size=100`,
      method: 'GET'
    });
    const b = await res.body('json');
    for (const it of (b.items || [])) {
      const v = it.value || {};
      const desc = (v.description || '').trim();
      for (const ep of (v.pythonRemote?.endpoints || [])) {
        if (ep.host && desc) NAME_OF[ep.host] = desc;
      }
    }
  } catch (e) { /* best-effort; fall back to sys.name */ }
}
function prettyName(ip, fallback) {
  const d = NAME_OF[ip] || fallback || ip;
  // Suffix so inferRole() returns 'wan-edge' (branches on top tier in Topology).
  return /sdwan|wan-edge/i.test(d) ? d : `${d} (sdwan)`;
}

async function dql(query) {
  // queryExecute is async: returns a requestToken; poll until state=SUCCEEDED.
  let r = await queryExecutionClient.queryExecute({ body: { query, maxResultRecords: 20000 } });
  const token = r.requestToken;
  const deadline = Date.now() + 60000;
  while (r.state === 'RUNNING' || r.state === 'NOT_STARTED') {
    if (Date.now() > deadline) throw new Error(`DQL poll timeout: ${query.slice(0, 80)}`);
    await new Promise(res => setTimeout(res, 500));
    r = await queryExecutionClient.queryPoll({ requestToken: token });
  }
  if (r.state !== 'SUCCEEDED') {
    throw new Error(`DQL ${r.state}: ${JSON.stringify(r).slice(0, 300)}`);
  }
  return r?.result?.records || r.records || [];
}

function esc(s) { return String(s).replace(/\\/g, '\\\\').replace(/,/g, '\\,').replace(/ /g, '\\ ').replace(/=/g, '\\='); }

function latest(rec) {
  const arr = rec.val || [];
  if (!arr.length) return [null, null];
  const tf = rec.timeframe || {};
  const start = new Date(tf.start).getTime();
  const end   = new Date(tf.end).getTime();
  const step  = (end - start) / arr.length;
  for (let i = arr.length - 1; i >= 0; i--) {
    if (arr[i] != null) return [arr[i], Math.round(start + step * (i + 1))];
  }
  return [null, null];
}

function ifDims(r) {
  return {
    'device.address': r['device.address'],
    'sys_name':       prettyName(r['device.address'], r['sys.name']),
    'if_index':       r['if.id'],
    'if_descr':       r['if.name'] || r['if.id'],
    'source':         'fortigate-bridge'
  };
}
function devDims(r) {
  return {
    'device.address': r['device.address'],
    'sys_name':       prettyName(r['device.address'], r['sys.name']),
    'source':         'fortigate-bridge'
  };
}
function oper(v) { return (Math.round(v) === 1) ? 1 : 2; }

function line(key, dims, value, ts) {
  const parts = [];
  for (const [k, v] of Object.entries(dims)) if (v != null && v !== '') parts.push(`${k}=${esc(v)}`);
  return `${key},${parts.join(',')} ${value} ${ts}`;
}

const IFBY = 'by:{`device.address`, `sys.name`, `if.id`, `if.name`}';
const DVBY = 'by:{`device.address`, `sys.name`}';
const FROM = 'from:-5m, interval:1m';

const MAPPINGS = [
  { q: `timeseries val=avg(fortigate.interface.status), ${IFBY}, ${FROM}`,          key: 'cno.if.oper_status',       dims: ifDims,  val: v => oper(v) },
  { q: `timeseries val=sum(fortigate.interface.bytes.in.count), ${IFBY}, ${FROM}`,  key: 'cno.if.in_octets.count',   dims: ifDims,  val: v => v },
  { q: `timeseries val=sum(fortigate.interface.bytes.out.count), ${IFBY}, ${FROM}`, key: 'cno.if.out_octets.count',  dims: ifDims,  val: v => v },
  { q: `timeseries val=sum(fortigate.interface.errors.in.count), ${IFBY}, ${FROM}`, key: 'cno.if.in_errors.count',   dims: ifDims,  val: v => v },
  { q: `timeseries val=sum(fortigate.interface.errors.out.count), ${IFBY}, ${FROM}`,key: 'cno.if.out_errors.count',  dims: ifDims,  val: v => v },
  { q: `timeseries val=avg(fortigate.cpu.usage), ${DVBY}, ${FROM}`,                 key: 'cno.device.cpu_usage',     dims: devDims, val: v => v }
];

export default async function () {
  const now = Date.now();
  const lines = [];
  const summary = {};

  // Pull the IP->description map before any metrics so sys_name gets the real site code.
  await loadDeviceNames();

  // Run all metric queries in parallel.
  const results = await Promise.all(MAPPINGS.map(async m => {
    const rows = await dql(m.q);
    let emitted = 0;
    for (const rec of rows) {
      try {
        const [v, ts] = latest(rec);
        if (v == null) continue;
        const d = m.dims(rec);
        if (!d['device.address']) continue;
        lines.push(line(m.key, d, m.val(v), ts));
        emitted++;
      } catch (_) {}
    }
    return { key: m.key, rows: rows.length, emitted };
  }));
  for (const r of results) summary[r.key] = { rows: r.rows, emitted: r.emitted };

  // Speed lives on the if.speed DIMENSION, pull via fetch metric.series.
  const speedRows = await dql('fetch metric.series, from:-5m | filter metric.key == "fortigate.interface.speed" | fields `device.address`, `sys.name`, `if.id`, `if.name`, `if.speed`');
  let speedEmitted = 0;
  for (const r of speedRows) {
    if (!r['device.address']) continue;
    const sp = parseInt(r['if.speed'] || '0', 10);
    lines.push(line('cno.if.high_speed', ifDims(r), isFinite(sp) ? sp : 0, now));
    speedEmitted++;
  }
  summary['cno.if.high_speed'] = { rows: speedRows.length, emitted: speedEmitted };

  // TOPOLOGY: hub-and-spoke edges from fortigate.tunnel.* so the Topology page has structure
  // to render. FortiGate's tunnel dimension carries a NAME (e.g. 'Hub-A') but not a
  // remote IP, so each named tunnel is treated as a virtual hub with a deterministic
  // RFC-5737 TEST-NET-3 address (203.0.113.0/24). This is clearly fake per RFC and will never
  // collide with real devices in the fleet. Pattern mirrors scripts/api_bridge.py.
  const tunnelRows = await dql('fetch metric.series, from:-10m | filter metric.key == "fortigate.tunnel.bytes.in.count" | fields `device.address`, `sys.name`, tunnel');
  const hubIp = (name) => {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) & 0xffffff;
    return `203.0.113.${(h % 254) + 1}`;
  };
  const seenEdge = new Set();
  let depEmitted = 0;
  for (const r of tunnelRows) {
    const ip = r['device.address']; const tun = r['tunnel'];
    if (!ip || !tun) continue;
    const edgeKey = `${ip}->${tun}`;
    if (seenEdge.has(edgeKey)) continue; seenEdge.add(edgeKey);
    const dims = {
      // Both labels: real description + role suffix so Topology stacks them on distinct tiers
      // (hubs on 'core', branches on 'wan-edge' via inferRole substring match).
      'device.name':      prettyName(ip, r['sys.name']).toLowerCase(),
      'device.address':   ip,
      'upstream.name':    `${tun} core`,
      'upstream.address': hubIp(tun),
      'link_type':        'sdwan',
      'discovery':        'api',
      'source':           'fortigate-bridge'
    };
    lines.push(line('cno.dep.uses', dims, 1, now));
    depEmitted++;
  }
  summary['cno.dep.uses'] = { rows: tunnelRows.length, emitted: depEmitted };

  if (!lines.length) return { ingested: 0, summary, note: 'nothing to ingest' };

  // Classic metric ingest via fetch(). httpClient.send auto-attaches the workflow Platform
  // bearer which collides with our Api-Token on classic endpoints ('Invalid app context').
  // fetch() does not inject headers, so Api-Token wins cleanly. External hosts ARE allowed
  // from fetch() in the workflow JS runtime even though httpClient blocks them.
  const body = lines.join('\n') + '\n';
  let status = 0, respBody = '';
  try {
    const res = await fetch(`https://${INGEST_HOST}/api/v2/metrics/ingest`, {
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
        'Authorization': `Api-Token ${INGEST_TOKEN}`
      },
      body
    });
    status = res.status;
    respBody = await res.text().catch(() => '');
  } catch (e) {
    status = -1;
    respBody = String(e.message || e);
  }
  return { ingested: lines.length, httpStatus: status, httpBody: String(respBody).slice(0, 500), sampleLine: lines[0] || '', summary };
}
